**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("wiek.txt");
    int wiek;
    int hist[10] = {0};
    while (plik >> wiek) {
        hist[wiek / 10]++;
    }

    // a)
    cout << "a) Histogram:" << endl;
    int maxDekada = -1, maxIle = 0;
    for (int i = 1; i <= 9; i++) {
        if (hist[i] > 0) {
            cout << "   [" << i*10 << "-" << i*10+9 << "]: " << hist[i] << endl;
        }
        if (hist[i] > maxIle) {
            maxIle = hist[i];
            maxDekada = i;
        }
    }

    // b)
    cout << endl << "b) Najliczniejsze dekady:";
    bool first = true;
    for (int i = 1; i <= 9; i++) {
        if (hist[i] == maxIle) {
            if (!first) cout << " i";
            cout << " [" << i*10 << "-" << i*10+9 << "]";
            first = false;
        }
    }
    cout << " (po " << maxIle << " osoby)" << endl;
    return 0;
}
```

**Wyjasnienie**: Tablica `hist[10]` sluzy jako tablica czestotliwosci. Indeks to numer dekady (wiek/10). Po wypelnieniu tablicy wypisujemy niepuste dekady i szukamy maksimum.

